// Convert explicitly declared Windows-1251 pages before parsing HTML.
String webCP1251(const String &s){String out;out.reserve(s.length()*2);for(unsigned i=0;i<s.length();i++){uint8_t c=s[i];uint16_t u=c;if(c>=192)u=0x410+c-192;else if(c==168)u=0x401;else if(c==184)u=0x451;else if(c==160)u=32;else if(c>=128)u='?';if(u<128)out+=(char)u;else{out+=(char)(0xC0|(u>>6));out+=(char)(0x80|(u&63));}}return out;}
void webInit(){if(webReady)return;webReady=true;if(!webPrefs.begin("webreader",false))return;webHistCount=min(20,(int)webPrefs.getUChar("hc",0));webMarkCount=min(20,(int)webPrefs.getUChar("bc",0));for(int i=0;i<20;i++){String k=String(i);if(i<webHistCount){webHistory[i]={webPrefs.getString(("hu"+k).c_str(),""),webPrefs.getString(("ht"+k).c_str(),"")};}if(i<webMarkCount){webMarks[i]={webPrefs.getString(("bu"+k).c_str(),""),webPrefs.getString(("bt"+k).c_str(),"")};}}}
void webStore(bool marks){auto a=marks?webMarks:webHistory;int n=marks?webMarkCount:webHistCount;String prefix=marks?"b":"h";for(int i=0;i<n;i++){webPrefs.putString((prefix+"u"+i).c_str(),a[i].address);webPrefs.putString((prefix+"t"+i).c_str(),a[i].label);}webPrefs.putUChar((prefix+"c").c_str(),n);}
